Method.Source:
/// <summary>
/// Returns the default printer settings for the specified PrintSetupOriginalCopy enumeration value.
/// </summary>
/// <param name = "_printCopyOriginal">PrintSetupOriginalCopy</param>
/// <returns>eturns the default printer settings</returns>
public container getDefaultPrintJobSettings(PrintSetupOriginalCopy _printCopyOriginal)
{
    if (_printCopyOriginal == PrintSetupOriginalCopy::Original)
    {
        return PurchFormLetter::getPrinterSettingsFormletter(DocumentStatus::None,PrintSetupOriginalCopy::Original);
    }
    else
    {
        return PurchFormLetter::getPrinterSettingsFormletter(DocumentStatus::None,PrintSetupOriginalCopy::Copy);
    }
}

/// <summary>
/// The PrintMgmtDocumentType enumeration value that specifies what document this FormLetterReport
/// class controls.
/// </summary>
/// <returns>Returns the PrintMgmtDocumentType enumeration value that specifies what document this FormLetterReport class controls.</returns>
public PrintMgmtDocumentType getPrintMgmtDocumentType()
{
    return PrintMgmtDocumentType::METArrivalOverviewDockCopy;
}

/// <summary>
/// The PrintMgmtHierarchyType enumeration value that specifies what hierarchy this FormLetterReport class uses.
/// </summary>
/// <returns>Returns the PrintMgmtHierarchyType enumeration value that specifies what hierarchy this FormLetterReport class uses</returns>
public PrintMgmtHierarchyType getPrintMgmtHierarchyType()
{
    return PrintMgmtHierarchyType::Purch;
}

/// <summary>
/// The PrintMgmtNodeType enumeration value that specifies what node this FormLetterReport class uses.
/// </summary>
/// <returns>Returns the PrintMgmtNodeType enumeration value that specifies what node this FormLetterReport class uses</returns>
public PrintMgmtNodeType getPrintMgmtNodeType()
{
    return PrintMgmtNodeType::PurchTable;
}
